--- transit filter ---
table inet antrieb_transit {
	chain transit_input {
		type filter hook input priority -50; policy accept;
		iifname "eth1" ip saddr != 10.91.0.10 tcp dport 179 counter packets 0 bytes 0 drop
		iifname "eth2" ip saddr != 10.92.0.10 tcp dport 179 counter packets 0 bytes 0 drop
		iifname != "eth1" iifname != "eth2" tcp dport 179 counter packets 2 bytes 120 drop
	}

	chain transit_forward {
		type filter hook forward priority -50; policy drop;
		ct state established,related counter packets 13 bytes 1092 accept
		iifname "eth1" oifname "eth2" ip saddr 198.18.201.2 ip daddr 198.18.202.3 counter packets 2 bytes 168 accept
		iifname "eth2" oifname "eth1" ip saddr 198.18.202.3 ip daddr 198.18.201.2 counter packets 1 bytes 84 accept
	}
}
